<?php
/** Order summary refreshed by native checkout AJAX. @version 11.2.0 */
defined( 'ABSPATH' ) || exit;
?>
<div class="<?php echo ! empty( $mobile_summary ) ? 'checkout-mobile-review-order-table' : 'woocommerce-checkout-review-order-table'; ?>" data-subtotal="<?php echo esc_attr( WC()->cart->get_cart_contents_total() ); ?>">
    <h2 class="screen-reader-text"><?php esc_html_e( 'Order summary', 'auracast' ); ?></h2>
    <div class="checkout-summary-products"><?php do_action( 'woocommerce_review_order_before_cart_contents' ); foreach ( WC()->cart->get_cart() as $cart_item_key => $cart_item ) : $_product = apply_filters( 'woocommerce_cart_item_product', $cart_item['data'], $cart_item, $cart_item_key ); if ( ! $_product || ! $_product->exists() || $cart_item['quantity'] < 1 || ! apply_filters( 'woocommerce_checkout_cart_item_visible', true, $cart_item, $cart_item_key ) ) { continue; } $parent = $_product->is_type( 'variation' ) ? wc_get_product( $_product->get_parent_id() ) : false; $name = $parent ? $parent->get_name() : $_product->get_name(); ?>
        <div class="checkout-summary-product <?php echo esc_attr( apply_filters( 'woocommerce_cart_item_class', 'cart_item', $cart_item, $cart_item_key ) ); ?>"><div class="checkout-summary-image"><?php echo apply_filters( 'woocommerce_cart_item_thumbnail', $_product->get_image( 'woocommerce_thumbnail' ), $cart_item, $cart_item_key ); ?><span class="checkout-quantity-badge"><?php echo (int) $cart_item['quantity']; ?></span></div><div class="checkout-summary-description"><p><?php echo wp_kses_post( apply_filters( 'woocommerce_cart_item_name', $name, $cart_item, $cart_item_key ) ); ?></p><?php echo wc_get_formatted_cart_item_data( $cart_item, false, $name ); ?></div><div class="checkout-summary-price"><?php echo wp_kses_post( apply_filters( 'woocommerce_cart_item_subtotal', WC()->cart->get_product_subtotal( $_product, $cart_item['quantity'] ), $cart_item, $cart_item_key ) ); ?></div></div>
    <?php endforeach; do_action( 'woocommerce_review_order_after_cart_contents' ); ?></div>
    <?php if ( wc_coupons_enabled() ) : $discount_id = ! empty( $mobile_summary ) ? 'checkout-mobile-discount-code' : 'checkout-discount-code'; ?><div class="checkout-discount"><label class="screen-reader-text" for="<?php echo esc_attr( $discount_id ); ?>"><?php esc_html_e( 'Discount code', 'auracast' ); ?></label><input type="text" class="checkout-discount-code" id="<?php echo esc_attr( $discount_id ); ?>" placeholder="<?php esc_attr_e( 'Discount code', 'auracast' ); ?>" autocomplete="off"><button type="button" class="checkout-apply-coupon"><?php esc_html_e( 'Apply', 'auracast' ); ?></button><div class="checkout-coupon-status" role="status" aria-live="polite"></div></div><?php endif; ?>
    <table class="checkout-cost-summary"><caption class="screen-reader-text"><?php esc_html_e( 'Cost summary', 'auracast' ); ?></caption><tbody><tr class="cart-subtotal"><th><?php esc_html_e( 'Subtotal', 'woocommerce' ); ?></th><td><?php wc_cart_totals_subtotal_html(); ?></td></tr>
        <?php foreach ( WC()->cart->get_coupons() as $code => $coupon ) : ?><tr class="cart-discount coupon-<?php echo esc_attr( sanitize_title( $code ) ); ?>"><th><?php wc_cart_totals_coupon_label( $coupon ); ?></th><td><?php wc_cart_totals_coupon_html( $coupon ); ?></td></tr><?php endforeach; ?>
        <?php if ( WC()->cart->needs_shipping() ) : ?><tr class="checkout-shipping-total"><th><?php esc_html_e( 'Shipping', 'woocommerce' ); ?></th><td><?php echo wp_kses_post( WC()->cart->get_cart_shipping_total() ); ?></td></tr><?php endif; ?>
        <?php foreach ( WC()->cart->get_fees() as $fee ) : ?><tr class="fee"><th><?php echo esc_html( $fee->name ); ?></th><td><?php wc_cart_totals_fee_html( $fee ); ?></td></tr><?php endforeach; ?>
        <?php if ( wc_tax_enabled() && ! WC()->cart->display_prices_including_tax() ) : if ( 'itemized' === get_option( 'woocommerce_tax_total_display' ) ) : foreach ( WC()->cart->get_tax_totals() as $tax ) : ?><tr class="tax-rate"><th><?php echo esc_html( $tax->label ); ?></th><td><?php echo wp_kses_post( $tax->formatted_amount ); ?></td></tr><?php endforeach; else : ?><tr class="tax-total"><th><?php echo esc_html( WC()->countries->tax_or_vat() ); ?></th><td><?php wc_cart_totals_taxes_total_html(); ?></td></tr><?php endif; endif; ?>
        <?php do_action( 'woocommerce_review_order_before_order_total' ); ?><tr class="order-total"><th><?php esc_html_e( 'Total', 'woocommerce' ); ?></th><td><span class="checkout-currency-code"><?php echo esc_html( get_woocommerce_currency() ); ?></span><?php wc_cart_totals_order_total_html(); ?></td></tr><?php do_action( 'woocommerce_review_order_after_order_total' ); ?>
    </tbody></table>
</div>
